from datetime import datetime, timezone
from zoneinfo import ZoneInfo


_TARGET_TIMEZONES = {
    "analytics": ZoneInfo("Asia/Shanghai"),
    "public_api": timezone.utc,
}


def format_timestamp(iso_timestamp, target):
    """Format a timezone-aware ISO timestamp for a project consumer."""
    try:
        target_timezone = _TARGET_TIMEZONES[target]
    except KeyError as exc:
        raise ValueError(f"Unknown timestamp target: {target}") from exc

    # Python 3.11+ accepts the ISO 8601 UTC designator directly.
    parsed = datetime.fromisoformat(iso_timestamp)
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError("iso_timestamp must include a timezone")

    return parsed.astimezone(target_timezone).strftime("%Y-%m-%d %H:%M")

