import unittest

from timestamps import format_timestamp


class FormatTimestampTests(unittest.TestCase):
    def test_analytics_converts_to_shanghai_time(self):
        self.assertEqual(
            format_timestamp("2024-01-01T00:30:00+00:00", "analytics"),
            "2024-01-01 08:30",
        )

    def test_public_api_keeps_utc(self):
        self.assertEqual(
            format_timestamp("2024-01-01T00:30:00Z", "public_api"),
            "2024-01-01 00:30",
        )

    def test_unknown_target_raises_value_error(self):
        with self.assertRaises(ValueError):
            format_timestamp("2024-01-01T00:30:00Z", "internal")

    def test_naive_timestamp_is_rejected(self):
        with self.assertRaises(ValueError):
            format_timestamp("2024-01-01T00:30:00", "public_api")


if __name__ == "__main__":
    unittest.main()

